starter_code:
function Component({ name }) {
  // TODO: return a <div className="greeting">Hello, {name}!</div>
}

test_cases.assertion_script:
const container = document.createElement('div');
document.body.appendChild(container);
ReactDOM.render(React.createElement(Component, { name: 'World' }), container);
const el = container.querySelector('.greeting');
assert.ok(el, 'No element with class "greeting" was rendered');
assert.strictEqual(el.textContent, 'Hello, World!');

const container = document.createElement('div');
document.body.appendChild(container);
ReactDOM.render(React.createElement(Component, { name: 'Aizentify' }), container);
const el = container.querySelector('.greeting');
assert.ok(el, 'No element with class "greeting" was rendered');
assert.strictEqual(el.textContent, 'Hello, Aizentify!');
